import {chromium} from 'playwright';
import {createServer} from 'node:http';
import {readFile} from 'node:fs/promises';
import {DatabaseSync} from 'node:sqlite';
import assert from 'node:assert/strict';
import {collect,report} from '../workers/analytics/index.mjs';
import manifest from '../workers/analytics/pages.json' with {type:'json'};
const sitemap=await readFile('dist/sitemap.xml','utf8');assert.deepEqual(Object.keys(manifest).sort(),[...sitemap.matchAll(/<loc>https:\/\/raahhi.com([^<]*)<\/loc>/g)].map(m=>m[1]).sort(),'All published routes are allowlisted for analytics');
const sqlite=new DatabaseSync(':memory:');sqlite.exec(await readFile('workers/migrations/0002_visitor_activity.sql','utf8')+await readFile('workers/migrations/0003_visitor_network_details.sql','utf8'));
const DB={prepare(sql){let args=[];const s={bind(...v){args=v;return s;},async first(){return sqlite.prepare(sql).get(...args)||null;},async all(){return {results:sqlite.prepare(sql).all(...args)};},async run(){return {meta:{changes:Number(sqlite.prepare(sql).run(...args).changes)}};}};return s;},async batch(statements){sqlite.exec('BEGIN');try{const out=[];for(const s of statements)out.push(await s.run());sqlite.exec('COMMIT');return out;}catch(e){sqlite.exec('ROLLBACK');throw e;}}};
const env={DB,TURNSTILE_SECRET:'test-only-secret'},API='https://raahhi-enquiries.asif-772.workers.dev/api/activity';
const server=createServer(async(req,res)=>{const url=new URL(req.url,'http://local'),p=url.pathname;try{if(p==='/api/me'||p==='/api/leads'){res.setHeader('Content-Type','application/json');res.end(JSON.stringify(p==='/api/me'?{email:'test@example.com'}:{leads:[],cursor:null}));return;}if(p.startsWith('/api/visitor')){const r=await report(url,env);res.statusCode=r.status;res.setHeader('Content-Type','application/json');res.end(await r.text());return;}const file=p==='/visitor-dashboard/'?'workers/leads/dashboard.html':p==='/dashboard.js'||p==='/visitors.js'?'workers/leads'+p:'dist'+(p.endsWith('/')?p+'index.html':p);res.setHeader('Content-Type',p.endsWith('.js')?'text/javascript':p.endsWith('.css')?'text/css':p.endsWith('.svg')?'image/svg+xml':p.endsWith('.webp')?'image/webp':'text/html');res.end(await readFile(file));}catch{res.statusCode=404;res.end();}});
await new Promise(r=>server.listen(0,'127.0.0.1',r));const base='http://127.0.0.1:'+server.address().port,browser=await chromium.launch();
try{
 const context=await browser.newContext({viewport:{width:390,height:900}}),p=await context.newPage(),errors=[],payloads=[];p.on('pageerror',e=>errors.push(e.message));
 await context.route('**/*',r=>r.request().url().startsWith(base)?r.continue():r.abort());
 await context.route(API,async route=>{const request=route.request(),headers={Origin:'https://raahhi.com','Content-Type':'application/json','CF-Connecting-IP':'192.0.2.44','User-Agent':request.headers()['user-agent']||''};if(request.method()==='POST')payloads.push(request.postDataJSON());const r=await collect(new Request(API,{method:request.method(),headers,body:request.method()==='POST'?request.postData():undefined}),env);await route.fulfill({status:r.status,headers:{...Object.fromEntries(r.headers),'Access-Control-Allow-Origin':'*'},body:await r.text()});});
 const open=async path=>{await p.goto(base+path);await p.waitForFunction(()=>document.getElementById('analyticsChoice'));};
 await open('/');assert.equal(payloads.length,0,'No analytics before consent');await p.getByRole('button',{name:'Decline analytics',exact:true}).click();assert.equal(await p.locator('#analyticsChoice').isVisible(),false,'Consent choice dismisses banner');await open('/activities/dubai/evening-desert-safari/');assert.equal(payloads.length,0,'Declining persists across pages');
 await p.getByRole('button',{name:'Analytics preferences',exact:true}).click();let response=p.waitForResponse(r=>r.url()===API&&r.request().method()==='POST');await p.getByRole('button',{name:'Allow analytics',exact:true}).click();await response;const id=payloads[0].sessionId;assert.equal(sqlite.prepare('SELECT COUNT(*) n FROM visitor_sessions').get().n,1,'A visitor without an enquiry appears');assert.equal(payloads[0].events[0].page,'/activities/dubai/evening-desert-safari/');
 await p.evaluate(()=>openCallback());await p.locator('#callbackName').fill('PRIVATE customer name');await p.locator('#callbackPhone').fill('+919876543210');await p.evaluate(()=>closeModal('contactModal'));
 // A controlled click exercises the real analytics listener without opening WhatsApp.
 await p.evaluate(()=>document.querySelector('a[href^="https://wa.me/"]').addEventListener('click',e=>e.preventDefault(),{once:true}));response=p.waitForResponse(r=>r.url()===API&&r.request().method()==='POST');await p.locator('a[href^="https://wa.me/"]').first().click();await response;
 const events=sqlite.prepare('SELECT * FROM visitor_events ORDER BY sequence').all();assert(events.some(e=>e.type==='enquiry_open'));assert(events.some(e=>e.type==='form_start'));assert(events.some(e=>e.type==='whatsapp_click'));assert(!JSON.stringify(payloads).includes('PRIVATE'));assert(!JSON.stringify(payloads).includes('9876543210'),'Form fields never enter analytics');
 response=p.waitForResponse(r=>r.url()===API&&r.request().method()==='POST');await open('/contact/');await response;assert.equal(payloads.at(-1).sessionId,id,'Session spans full page navigation');assert.equal(sqlite.prepare('SELECT last_page FROM visitor_sessions').get().last_page,'/contact/');
 await p.getByRole('button',{name:'Analytics preferences',exact:true}).click();await p.getByRole('button',{name:'Decline analytics',exact:true}).click();const count=payloads.length;await open('/visas/singapore/');await p.locator('#visaEnqName').count();assert.equal(payloads.length,count,'Withdrawing consent stops collection');assert.equal(await p.evaluate(()=>sessionStorage.getItem('raahhi.analytics.session.v2')),null);
 const privacy=await browser.newContext();await privacy.addInitScript(()=>Object.defineProperty(navigator,'globalPrivacyControl',{value:true}));await privacy.route('**/*',r=>r.request().url().startsWith(base)?r.continue():r.abort());const gp=await privacy.newPage();await gp.goto(base+'/contact/');await gp.waitForFunction(()=>document.getElementById('analyticsChoice'));assert.equal(await gp.locator('#analyticsChoice').isVisible(),false);assert.equal(await gp.locator('#analyticsChoice button').first().isEnabled(),false);await privacy.close();
 await p.goto(base+'/visitor-dashboard/');await p.getByRole('button',{name:'Visitor activity',exact:true}).click();await p.waitForFunction(()=>document.querySelector('#visitorList .lead'));assert((await p.locator('#visitorTotals').innerText()).includes('No saved enquiry'));await p.locator('#visitorList .lead').first().click();await p.waitForFunction(()=>document.querySelector('.visitor-timeline'));assert((await p.locator('#visitorDetail').innerText()).includes('Evening Desert Safari'));assert((await p.locator('#visitorDetail').innerText()).includes('Clicked WhatsApp'));assert((await p.locator('#visitorDetail').innerText()).includes('192.0.2.44'));assert((await p.locator('#visitorDetail').innerText()).includes('Chrome'));assert.equal(await p.locator('#enquiriesView').isVisible(),false);await p.getByRole('button',{name:'Customer enquiries',exact:true}).click();assert.equal(await p.locator('#enquiriesView').isVisible(),true);assert.deepEqual(errors,[]);
 console.log('PASS consent/decline/withdrawal/GPC, consented non-enquirer journeys with IP/browser details across pages, product/form/WhatsApp events, no form data, separate dashboard timeline and all 270 route mappings.');
}finally{await browser.close();server.close();sqlite.close();}
